export type Id = string;
export type CliId = 'claude' | 'codex' | 'gemini' | string;
export interface CliStatus { id: CliId; name: string; installed: boolean; version?: string; signedIn: boolean; models: string[]; note?: string; authState?: 'signedIn'|'signedOut'|'unknown'; features?: CliFeatures; custom?: boolean }   // features = what Harbor can use on this CLI (CHANGELOG 0.1.31); custom = added by the user as a CustomCliDescriptor
export interface CliFeatures { images: boolean; resume: boolean; structuredOutput: boolean; permissionModes: boolean; readOnly: boolean; mcp: boolean; nativeSkills: boolean; usageReadings: boolean }   // a missing feature never blocks routing; it changes what Harbor does (no resume = handoff text every turn, no images = vision work goes elsewhere, no readOnly = no read-only work unless the user accepted it)
export type CliArg = string | string[];   // a string[] is a group: dropped whole when any placeholder in it expands to nothing (e.g. ["--model","{model}"] with the CLI's default model)
export interface CustomCliDescriptor {   // a user-described CLI (Settings > Connections > Add CLI), stored in the data folder's custom-clis.json; never read from a project folder (CHANGELOG 0.1.31)
 id: CliId; name: string; exe: string;   // id: lowercase letters, digits and dashes, not a built-in id; exe: absolute path of the approved executable
 version?: { args: string[] };   // default ["--version"]
 status?: { args: string[]; signedInExit?: number; signedOutPattern?: string };   // signedOutPattern = plain text (case-insensitive) that means "signed out"; absent status = sign-in unknown
 login?: { args: string[] };
 run: {
  args: CliArg[];   // placeholders: {model} {effort} {cwd} {promptFile}; whole-argument slots {resumeArgs} {effortArgs} {permissionArgs} {imageArgs} (appended at the end when absent)
  prompt?: 'stdin' | 'file';   // default stdin; file = written to a temp file passed as {promptFile}
  env?: Record<string, string>;   // extra variables you typed; the CLI otherwise gets only a fixed allowlist of Windows variables
  output?: { format: 'text' | 'jsonl'; map?: { text?: string; session?: string; done?: string; error?: string; usage?: { input?: string; output?: string } } };   // map paths: $.a.b[0].c; done may be "$.type==result"
  resume?: { args: CliArg[] };   // {sessionId} allowed here only; absent = no resume (Harbor sends its handoff text instead)
  effort?: Partial<Record<'low' | 'medium' | 'high', string[]>>;
  permissions?: Partial<Record<'read-only' | 'edit' | 'full', string[]>>;   // no read-only entry = no read-only work unless acceptReadOnlyRisk
  image?: { args: string[] };   // per image, {path} = the image file; absent = not vision-capable
  readDir?: { args: string[] };   // per extra folder the run may read (enabled skills outside its working folder), {path} = the folder; slot {readDirArgs}; absent = small skills are inlined in the prompt instead (CHANGELOG 0.1.32)
  mcp?: { args: string[] };   // how to hand the CLI an MCP config file, {mcpConfigFile} = a per-run JSON file {"mcpServers":{"<name>":{"type":"stdio","command","args","env"} | {"type":"http"|"sse","url","headers"}}} (Claude Code's shape); slot {mcpArgs}; present = features.mcp (CHANGELOG 0.1.36)
 };
 models?: Array<{ id: string; tier?: 'cheap' | 'standard' | 'strong'; strengths?: string[] }>;   // catalog entries (capabilities.json entries for the same cli/model win); default one 'default' model with no strengths
 acceptReadOnlyRisk?: boolean;   // the user accepted that this CLI may write during read-only roles (planners, reviewers, plan mode)
 approvedHash?: string; approvedAt?: number;   // set by Harbor on save: sha256 of the executable the user approved, and when; a changed file blocks the CLI until approved again
}
export interface CliTemplate { id: string; name: string; description: string; verified?: string; descriptor: Omit<CustomCliDescriptor, 'exe'> & { exe?: string } }   // verified = which CLI version the flags were checked against with --help
export interface CliDryRunStep { name: 'version' | 'status' | 'prompt'; command: string; exitCode: number | null; stdout: string; stderr: string; error?: string; durationMs: number }   // stdout/stderr clipped for display
export interface CliDryRun { ok: boolean; problems?: string[]; version?: string; authState?: 'signedIn' | 'signedOut' | 'unknown'; steps: CliDryRunStep[]; parsed?: { text?: string; sessionId?: string; inputTokens?: number; outputTokens?: number; chunks: number; ok?: boolean; error?: string } }   // problems = descriptor errors (nothing was run when present); parsed = what Harbor understood from the prompt run
export type SkillSource = 'library' | 'project' | 'claude' | 'codex';   // library = %APPDATA%\Harbor\skills; project = <project>\.harbor\skills; claude/codex = found in that CLI's own skills folder (read-only)
export interface Skill {   // a folder with a SKILL.md (frontmatter name + description, body = instructions) and optional resources (CHANGELOG 0.1.32)
 id: string; name: string; description: string; source: SkillSource;   // id = "<source>:<folder>" (stable; claude/codex ids also say user/ or project/)
 path: string; readOnly: boolean;   // path = absolute folder; readOnly = Harbor never changes it (everything but the library)
 enabled: boolean; defaultEnabled: boolean;   // enabled = used for the project asked about (or the global default without one); defaultEnabled = the global default
 files: number; bytes: number; hasScripts: boolean;   // hasScripts = contains scripts or programs; Harbor never runs them, agents only through their normal tool permissions
 hash?: string; importedFrom?: string; importedAt?: number;   // library: sha256 of the files recorded at import, and where they came from
 problems?: string[];   // why it cannot be used (e.g. no description); such a skill is never given to an agent
}
export interface SkillFile { path: string; bytes: number; script?: boolean }   // path relative to the skill folder, forward slashes
export interface SkillDetail extends Skill { text: string; truncated?: boolean; fileList: SkillFile[]; currentHash?: string; modified?: boolean }   // text = SKILL.md as written; modified = library files no longer match the hash recorded at import
export type SkillImportSource = { kind: 'folder'; path: string } | { kind: 'zip'; path: string } | { kind: 'github'; ref: string };   // github: https://github.com/owner/repo[/tree/<ref>/<path>] or owner/repo[/path]
export interface SkillImportCandidate { name: string; description: string; dir: string; targetName: string; files: SkillFile[]; bytes: number; hasScripts: boolean; text?: string; hash?: string; problems?: string[] }   // dir = folder inside the source ('' = its root); targetName = library folder it would get (suffixed when the name is taken); text = SKILL.md
export interface SkillImportPreview {
 token?: string;   // pass to importSkills (or, for a GitHub listing, back as confirmDownload); absent when nothing can be imported
 source: string;   // exactly what is read: a folder or .zip path, or github.com/owner/repo@<commit>/<path>
 needsDownload?: boolean;   // GitHub listing: only names and sizes are known; nothing was downloaded yet
 fileCount: number; totalBytes: number;
 skills: SkillImportCandidate[];
 problems?: string[]; warnings?: string[];   // problems = refused (traversal, symlink, too large, ...); warnings = e.g. "contains scripts"
}
export type McpTransport = 'stdio' | 'http' | 'sse';   // stdio = a local command the CLI starts; http = streamable HTTP; sse = the older HTTP+SSE transport (Claude Code and custom CLIs only) (CHANGELOG 0.1.36)
export interface McpServerDraft {   // one entry of Harbor's MCP registry, stored as plain text in the data folder's mcp-servers.json; never exported, never in diagnostics or logs
 name: string; transport: McpTransport;   // name: 1-64 letters, digits, '-' or '_' (unique; tools show up as mcp__<name>__<tool>)
 command?: string; args?: string[]; env?: Record<string, string>;   // stdio: a bare command (npx, uvx) or an absolute path; env = extra variables for the server only
 url?: string; headers?: Record<string, string>;   // http/sse: http(s) URL and request headers
 allowUnattended?: boolean;   // its tools may run without asking: needed for CLIs that cannot ask Harbor (Codex, custom CLIs) and for Claude in auto mode; off = only Claude edit runs, where every tool call asks you
}
export interface McpServer extends McpServerDraft { enabled: boolean; defaultEnabled: boolean; updated?: number }   // enabled = for the project asked about (or the global default without one); defaults off
export interface McpTestResult { ok: boolean; transport: McpTransport; durationMs: number; serverName?: string; serverVersion?: string; protocolVersion?: string; tools?: string[]; error?: string; stderr?: string }   // what an MCP initialize + tools/list answered; stderr = the server's last output (entered env and header values masked)
export interface CliMcpServer { source: 'claude' | 'codex'; scope: 'user' | 'local' | 'project'; name: string; transport?: string; where: string }   // a server in that CLI's own configuration, listed read-only (name and kind only, never its command, URL or values); where = the file (home shown as ~)
// ---- Project lifecycle and publish (CHANGELOG 0.1.47). Desktop only: none of these methods is callable remotely.
export type ProjectTemplate = 'empty'|'node-ts'|'python'|'static-web';
export interface NewProjectDraft { name: string; parentDir?: string; template?: ProjectTemplate; github?: { create: true; visibility: 'private'|'public'; owner?: string } | { create: false }; firstPrompt?: string }   // name 1-80 characters, becomes the folder name (sanitised); parentDir default Settings.projectsDir; github absent = no repository
export interface CreateProjectResult { project: Project; path: string; remote?: string; conversationId?: Id; warnings: string[] }   // warnings = what was skipped or only partly done (no gh, no identity, push failed, ...)
export type DeleteScope = 'forget'|'worktrees'|'folder';   // forget = Harbor's records only; worktrees = also Harbor's worktrees and harbor/* branches; folder = also the project folder
export interface DeletePreview { projectId: Id; path: string; running: number; worktrees: { path: string; branch?: string; dirty: boolean; unmergedCommits: number }[]; branches: { name: string; unpushed: number; merged: boolean }[]; folder: { exists: boolean; dirty: boolean; unpushedCommits: number; hasRemote: boolean; sizeBytes?: number; outsideProjectsDir: boolean }; blockers: string[]; needsTypedName: { worktrees: boolean; folder: boolean } }   // read-only; running = agents that would be stopped; branches are harbor/* only; blockers refuse the folder level; needsTypedName = the scope that must be confirmed with the project name
export interface DeleteResult { removed: { records: boolean; worktrees: number; branches: number; folder: boolean }; warnings: string[] }
export interface PushSecretFinding { type: string; file: string; line: number }   // type, file and line only, never the value
export interface SecretScanSummary { findings: PushSecretFinding[]; total: number; allowed: number; fingerprint?: string; truncated?: boolean; failed?: boolean }   // findings = those the allowlist does not cover; fingerprint = identity of exactly these findings on this head (pass it back as pushBranch opts.secretOverride to push anyway)
export interface PushPreview { branch: string; remote?: string; upstream?: string; ahead: number; behind: number; isDefaultBranch: boolean; commits: { hash: string; subject: string }[]; secretScan?: SecretScanSummary; needsRemote: boolean; busy?: boolean }   // busy = an agent is running on this branch
export interface PushResult { ok: boolean; output: string; remote: string; branch: string; pullRequestUrl?: string }
export interface PullRequestDraft { branch: string; base?: string; title: string; body?: string; draft?: boolean }
export interface WorktreeInfo { path: string; projectId?: Id; projectName?: string; branch?: string; ageDays: number; sizeBytes?: number; merged: boolean; dirty: boolean; active: boolean; orphan: boolean; removable: boolean }   // one Harbor worktree folder; orphan = no project uses it any more; removable = not active, no uncommitted changes, and merged, applied, older than 14 days or orphaned
// ---- Track B, projects 2 (CHANGELOG 0.1.48 and later). Desktop only, like the lifecycle methods above.
export interface CloneProjectDraft { url: string; name?: string; parentDir?: string; firstPrompt?: string }   // url = https, ssh or scp-like git URL (no embedded credentials); name = folder and project name (default: the repository name); parentDir default Settings.projectsDir
export interface GithubRepo { slug: string; name: string; owner: string; description?: string; isPrivate: boolean; isFork?: boolean; updatedAt?: number; url: string }   // slug = owner/name; url = https clone URL; from `gh repo list`
export interface GithubRepoListOptions { owner?: string; limit?: number; refresh?: boolean }   // owner = an account or organisation (default: the signed-in account); limit 1-200 (default 100); refresh = skip the 5 minute cache
export interface GithubStatus { installed: boolean; loggedIn: boolean; account?: string }
export interface Project { id: Id; name: string; path: string; lastOpened: number; image?: string }   // image = small data: URL chosen by the user
export interface Conversation { id: Id; projectId: Id; title: string; updated: number; agentId: Id; pinned?: boolean; archived?: boolean; customTitle?: boolean; activity?: SessionActivity; reviewBase?: string; mode?: ConversationMode; goal?: string; deadline?: number; imported?: ImportedInfo; continuedFrom?: Id }   // agentId = main agent, or a subagent for direct chats; deadline = epoch ms the owner needs this conversation's work by (setConversationDeadline; CHANGELOG 0.1.27); imported = read-only history from another tool or a Harbor bundle (CHANGELOG 0.1.35); continuedFrom = the imported conversation this one continues (continueImported)
export type ChatImportSourceId = 'claude-code' | 'codex' | 'claude-export' | 'chatgpt-export';   // claude-code = ~\.claude\projects\*\*.jsonl; codex = ~\.codex\sessions; claude-export / chatgpt-export = an account export's conversations.json (or its .zip)
export interface ImportedInfo { source: ChatImportSourceId | 'bundle'; label: string; importedAt: number; started?: number; ended?: number; messages: number; skipped?: string[] }   // label = where it came from in words ("Claude Code", "Harbor bundle from Storefront"); started/ended = first and last message time in the original; skipped = what the importer left out (tool calls, thinking, unreadable lines, ...)
export interface ChatImportSourceInfo { id: ChatImportSourceId; name: string; kind: 'folder' | 'file'; available: boolean; location?: string; verified: boolean; note?: string }   // folder sources read the CLI's own folder (location, home shown as ~); file sources need the user to pick an export file. verified = the format was checked against real files
export interface ChatImportEntry { id: string; title: string; detail?: string; started?: number; updated?: number; bytes?: number; messages?: number }   // one chat that can be imported; folder sources list files only (nothing inside them is read before importConversation)
export interface ChatImportPreview { token?: string; source: ChatImportSourceId; label: string; entries: ChatImportEntry[]; problems?: string[]; skipped?: string[]; truncated?: boolean }   // token = pass to importConversation; problems = nothing can be imported; skipped = what the listing left out; truncated = more entries exist than are listed
export interface ChatImportResult { conversations: Conversation[]; skipped: string[] }   // skipped = chats that could not be imported, and what each imported chat left out
export interface BundleSelection { settings?: boolean; toolRules?: boolean; skillChoices?: boolean; conversations?: Id[]; skills?: string[]; images?: boolean }   // what an export should hold: routing preferences, tool rules, per-project skill choices, these conversations, these skills (ids from listSkills), and the image files of those conversations (otherwise only their names)
export interface BundleItem { kind: 'settings' | 'toolRules' | 'skillChoices' | 'checksFile' | 'conversation' | 'skill' | 'image'; key: string; label: string; detail?: string; bytes?: number }
export interface SecretFinding { where: string; kind: string; excerpt: string }   // where = which item; kind = what it looks like (private key, token, .env line, ...); excerpt = masked, never the full value
export interface BundleExportPreview { token: string; fileName: string; items: BundleItem[]; excluded: string[]; secrets: SecretFinding[]; bytes: number; notes?: string[] }   // exactly what exportBundle(token) writes; excluded = what a bundle never holds; secrets = the scan's findings (exporting then needs keepSecrets or redactSecrets)
export interface BundleExportResult { path: string; bytes: number; items: number; redacted?: number }
export interface BundlePreview { token?: string; version: number; supported: boolean; createdAt?: number; appVersion?: string; projectName?: string; items: BundleItem[]; conversations: Array<{ key: string; title: string; messages: number; decisions: number; images: number }>; settings?: ProjectSettings; toolRules?: Array<{ tool: string; prefix?: string; allowed: boolean }>; skillChoices?: Record<string, boolean>; checksFile?: string; skills?: SkillImportPreview; secrets: SecretFinding[]; problems?: string[]; warnings?: string[] }   // nothing is written by a preview; supported = this Harbor reads the bundle's version (otherwise problems says to update and there is no token); toolRules.allowed = Harbor would accept the rule (never-always commands are refused)
export interface BundleImportOptions { projectId: Id; settings?: boolean; replaceSettings?: boolean; toolRules?: boolean; skillChoices?: boolean; skills?: string[]; conversations?: string[] }   // the parts to bring in (default nothing); replaceSettings = allowed to replace routing overrides the project already has; skills = candidate names from the preview; conversations = keys from the preview
export interface BundleImportResult { conversations: Conversation[]; skills: Skill[]; applied: string[]; skipped: string[] }
export type EditorId = 'code' | 'code-insiders' | 'cursor' | 'windsurf';   // editors Harbor can open a folder or file in (CHANGELOG 0.1.25)
export type ConversationMode = 'default'|'auto'|'plan'|'goal';   // auto = no permission prompts; plan = read-only plan first; goal = keep going until done (needs `goal`)
export interface SessionActivity { state: 'queued'|'working'|'waiting'|'done'|'failed'|'stopped'; started?: number; updated: number; detail?: string; cli?: CliId; model?: string; complexity?: 'low'|'medium'|'high'; effort?: string }
export interface SearchHit { conversation: Conversation; projectName: string; excerpt?: string }
export interface ReviewSnapshot { conversationId: Id; capturedAt: number; files: Array<{ path: string; patch: string; source: string; untracked?: boolean }>; notes: string[] }
export interface GitBranch { name: string; head: string; subject: string; updated: number; current?: boolean; upstream?: string; ahead?: number; behind?: number; worktree?: string; agentId?: Id; agentTitle?: string; agentState?: AgentState }   // ahead/behind = against GitOverview.base; agent* = the Harbor helper that owns a harbor/* branch
export interface GitWorktree { path: string; head: string; branch?: string; changed: number; main?: boolean }   // changed = uncommitted files; main = the project folder itself
export interface GitOverview { projectId: Id; base?: string; current?: string; branches: GitBranch[]; worktrees: GitWorktree[]; notes: string[] }
export interface GitCommit { hash: string; parents: string[]; subject: string; author: string; time: number; refs: string[] }
export interface GitFileChange { path: string; status: 'added'|'modified'|'deleted'|'renamed'|'untracked'|'other'; oldPath?: string; additions?: number; deletions?: number; hidden?: boolean }   // hidden = credential file, diff never shown
export interface GitTarget { branch?: string; commit?: string }   // neither = uncommitted changes in the project folder
export type AgentRole ='main' | 'planner' | 'implementer' | 'reviewer' | 'other';
export type AgentState = 'queued' | 'working' | 'waiting' | 'done' | 'failed' | 'stopped';
export interface Agent { id: Id; projectId: Id; parentId?: Id; role: AgentRole; title: string; state: AgentState; cli: CliId; model: string; effort: 'low'|'medium'|'high'; worktree?: string; summary?: string; conversationId?: Id; priority?: number; paused?: boolean; testedCommit?: string; outdated?: boolean; result?: AgentResult; checks?: CheckOutcome[]; integration?: Integration; rollback?: Rollback; estimatedMinutes?: number; stopKind?: 'user'|'cap'|'restart'|'loop'|'spend' }   // stopKind = who stopped a stopped agent: the user, Harbor's time limit, a Harbor restart, Harbor's loop guard or a spend ceiling (absent = unknown, e.g. older records; CHANGELOG 0.1.42); estimatedMinutes = Harbor's estimate of the helper's wall minutes when it was delegated (a prior blended with calibration, never a promise); conversationId = the main-agent conversation that created this subagent; priority = higher starts first (absent = 0); paused = will not start while queued; testedCommit = exact commit a reviewer examined, or that Harbor's checks ran on; outdated = that branch moved since (computed); result = the helper's last HARBOR_RESULT; checks = commands Harbor itself ran on testedCommit; integration = set on an integrator (role 'other', run by Harbor itself, no CLI); rollback = set on a rollback agent (role 'other', run by Harbor itself, no CLI)
export interface Integration { target?: string; base?: string; branch?: string; head?: string; sources: IntegrationSource[]; conflicts?: string[]; applied?: boolean }   // target = user branch to fast-forward (absent until resolved: the project's checked-out branch); base = target's head when the run started; branch/head = the harbor/integrate-* branch and its head; conflicts = unmerged paths of the source that stopped the run; applied = applyIntegration moved target to head
export interface IntegrationSource { agentId: Id; branch?: string; commit?: string; state: 'pending'|'merged'|'conflict'; merge?: string }   // commit = the source head pinned (and merged by SHA) at run start; merge = the merge commit Harbor created for it on the integration branch (absent when it was already included)
export interface RollbackPreview { agentId?: Id; target?: string; targetHead?: string; supported?: boolean; merges?: RollbackMerge[]; files?: GitFileChange[]; laterCommits?: RollbackLaterCommit[]; dependents?: RollbackDependent[]; clean?: boolean|null; conflicts?: string[]; blockers?: string[]; notes?: string[] }   // read-only: nothing is changed. supported = the task reached target through merge commits Harbor can reverse; clean = reverting them on targetHead merges cleanly (null = could not be simulated); conflicts = paths of the first revert that would conflict; blockers = why a rollback may not run now
export interface RollbackMerge { commit: string; agentId?: Id; integrationId?: Id }   // a merge commit on the target that brought the task's work in (agentId = the helper merged; integrationId = the integrator that made it)
export interface RollbackLaterCommit { hash: string; subject?: string; files?: string[]; agentId?: Id; agentTitle?: string }   // a commit on the target after the task's merge that touches the same files (agent* = owning Harbor helper when known)
export interface RollbackDependent { agentId: Id; title?: string; state?: AgentState; reason: 'dependsOn'|'spec'|'help'|'overlap' }   // dependsOn = waited for the task; spec = used its report as spec; help = the task was created to help it; overlap = later work on the same files
export interface Rollback { taskId: Id; target?: string; base?: string; branch?: string; head?: string; merges: RollbackRevert[]; conflicts?: string[]; applied?: boolean }   // taskId = the agent whose merges are reverted; target = user branch to fast-forward (absent until resolved); base = target's head pinned at the first run; branch/head = the harbor/rollback-* branch and its head; merges = the task's merges on target, newest first (pinned with base); conflicts = unmerged paths of the revert that stopped the run; applied = applyIntegration moved target to head
export interface RollbackRevert { commit: string; agentId?: Id; integrationId?: Id; state: 'pending'|'reverted'|'conflict'; revert?: string }   // a RollbackMerge plus its progress; revert = the commit `git revert -m 1` made for it on the rollback branch
export interface AgentResult { outcome: 'done'|'partial'|'blocked'; summary: string; verdict?: 'approve'|'changes'; checks: Array<{ cmd: string; ok: boolean }>; commit?: string }   // self-reported (checks here are claims); verdict = reviewers; commit = what the run examined (reviewer: its testedCommit; edit helper: its branch head)
export interface CheckOutcome { cmd: string; ok: boolean; exitCode: number|null; timedOut?: boolean; durationMs: number }   // a .harbor/checks.json command Harbor ran itself (evidence)
export interface Attachment { name: string; mime: string; path?: string; url?: string; origin?: 'user' | 'screenshot' | 'agent' }   // path = absolute file under Harbor's data folder, set by main; url = harbor-file://attachments/<conversationId>/<file> for showing it (CHANGELOG 0.1.33); origin = attached by the user, captured by Harbor for an agent's HARBOR_SCREENSHOT, or a project image an agent showed (HARBOR_SHOW_IMAGE)
export interface ScreenshotSource { id: string; name: string; kind: 'screen' | 'window'; thumbnail?: string; suggested?: boolean }   // a window or screen the user may choose in a screenshot card; thumbnail = small data:image/png preview taken just now (never stored, never sent to a model); suggested = matches what the agent asked for (CHANGELOG 0.1.33)
export interface ScreenshotRequestInfo { target: 'screen' | 'window'; title?: string; why: string; agentRole?: AgentRole; agentTitle?: string; projectId?: Id; projectName?: string; recent?: boolean }   // what an agent's HARBOR_SCREENSHOT line asked for (its own words: a hint, never the capture target); recent = this agent had a capture less than a minute ago
export type DocumentKind = 'markdown'|'text'|'code'|'json'|'csv'|'image'|'svg'|'html'|'pdf'|'office'|'binary'|'tooLarge';   // how the viewer shows a file (CHANGELOG 0.1.34): pdf, office, binary and tooLarge carry no content (open in the default app or reveal instead)
export interface DocumentView { path: string; name: string; kind: DocumentKind; size: number; modified: number; root: 'project'|'worktree'|'attachments'|'skills'|'picked'; agentId?: Id; relPath?: string; language?: string; text?: string; html?: string; dataUrl?: string; mime?: string; unchanged?: boolean; canOpenExternally?: boolean; note?: string }   // path = real absolute path; relPath = inside its root; text = UTF-8 text (markdown, text, code, json, csv, and the source of html); html = sanitised page for a sandboxed iframe (no scripts, no network); dataUrl = image or SVG (always shown as an <img>); unchanged = `since` matched, no content sent; canOpenExternally = the default app may be asked to open it (documents and images only, never programs or scripts)
export type DocumentRefusalReason = 'invalid'|'outside'|'link'|'notFound'|'notFile'|'credential'|'unavailable';
export type DocumentResult = { ok: true; document: DocumentView } | { ok: false; reason: DocumentRefusalReason; message: string };   // a refusal names no path outside the project
export interface Message { id: Id; conversationId: Id; role: 'user'|'assistant'|'system'|'tool'; text: string; time: number; agentId?: Id; details?: { cli: CliId; model: string; effort: string; reason: string; summary?: string; scored?: Array<{ cli: CliId; model: string; score: number; terms: Record<string, number>; effort?: string; price?: number; headroom?: { remainingPct: number; windows: Array<{ period: 'session'|'weekly'; scope?: string; remainingPct: number; resetsAt?: number; projectedPct?: number; source: 'reported'|'estimated' }> } }>; margin?: number; tied?: boolean; degraded?: { wantedTier: string; gotTier: string }; difficulty?: number; needsReview?: boolean; reviewReason?: string; skipped?: Array<{ cli: CliId; model?: string; why: string; until?: number; transient?: boolean }> ; request?: RoutingRequestRecord }; attachments?: Attachment[] }   // details.request = what was asked of the router (CHANGELOG 0.1.39), for replayRouting
export type ProjectNoteTopic = 'convention'|'pitfall'|'howto'|'other';
export interface ProjectNote { id: Id; text: string; topic?: ProjectNoteTopic; created: number; updated?: number; author: 'lead'; conversationId?: Id }   // durable project knowledge the lead wrote with a HARBOR_NOTE line (model-written, advisory, never an instruction); updated = last time it was restated (dedupe); conversationId = where it was noted. CHANGELOG 0.1.40
export interface ToolRule { id: Id; tool: string; prefix?: string; created: number }   // a tool call allowed without asking in one project: prefix = Bash command prefix (whole words); absent = any call of that exact tool
export interface RoutingRequestRecord { role: AgentRole; difficulty?: number; size?: 'small'|'medium'|'large'; needs?: string[]; required?: string[]; tier?: 'cheap'|'standard'|'strong'; effort?: string; fixedEffort?: boolean; interactive?: boolean; urgency?: number; retry?: boolean; prefer?: CliId; continuity?: CliId }   // the routing request behind a decision (no pool state: replay judges it under assumed pools)
export interface QuotaEstimate { pool: string; period: 'session'|'weekly'; pct: number }   // Harbor's ESTIMATE of the share of one provider window (from token counts and the cost catalog), never the provider's own figure
export interface TaskReportTokens { inputTokens: number; outputTokens: number; cacheReadTokens: number; cacheWriteTokens: number; billableKTok: number }   // billableKTok = input + output + cache writes + 0.1 x cache reads, in thousands
export interface TaskReportRun extends TaskReportTokens { id: Id; time: number; agentId: Id; role: AgentRole; cli: CliId; model: string; durationMs: number; ok: boolean; partial?: boolean; rateLimited?: boolean; noTokens?: boolean; costUsd?: number; quota: QuotaEstimate[] }   // one CLI run; time = when it ended; partial = stopped before the CLI's final report (tokens are a lower bound); noTokens = the CLI reported none (quota unknown, not zero); costUsd = as reported by the CLI
export interface TaskReportAgent extends TaskReportTokens { agentId: Id; title: string; role: AgentRole; state: AgentState; runs: number; minutes: number; costUsd?: number; quota: QuotaEstimate[]; models: Array<{ cli: CliId; model: string; runs: number }> }
export interface TaskReportModel extends TaskReportTokens { cli: CliId; model: string; runs: number; minutes: number; roles: AgentRole[]; costUsd?: number; quota: QuotaEstimate[] }
export interface TaskReportDecision { messageId: Id; agentId?: Id; time: number; cli: CliId; model: string; effort: string; difficulty?: number; price?: number; needsReview?: boolean }   // a routing decision recorded on a message; price = the router's own scarcity-weighted estimate
export interface TaskReport { conversationId: Id; projectId: Id; generatedAt: number; totals: TaskReportTokens & { runs: number; failedRuns: number; partialRuns: number; runsWithoutTokens: number; agentMinutes: number; wallMinutes: number; costUsd?: number; quota: QuotaEstimate[] }; agents: TaskReportAgent[]; byModel: TaskReportModel[]; runs: TaskReportRun[]; decisions: TaskReportDecision[]; notes: string[] }   // agentMinutes = summed run time; wallMinutes = first run start to last run end; quota fields are estimates (see notes)
export type ResultRatingValue = 'up'|'down'|'redo-stronger';
export interface ResultRating { id: Id; time: number; rating: ResultRatingValue; note?: string; target: 'agent'|'message'; targetId: Id; projectId: Id; conversationId?: Id; agentId?: Id; role?: AgentRole; cli: CliId; model: string; effort?: string; needs?: string[]; difficulty?: number }   // local evidence about one result; never edits capabilities.json
export interface RatingSummaryRow { cli?: CliId; model?: string; need?: string; up: number; down: number; redoStronger: number; total: number; approval: number }   // approval = up / total (0..1)
export interface RoutingReplayOptions { projectId?: Id; conversationId?: Id; catalog?: unknown[]; settings?: Partial<Settings>; limit?: number }   // catalog = capabilities.json-style entries for the what-if (absent = current); settings = a patch over the current settings (validated like setSettings); limit = newest N decisions (default 200, max 2000)
export interface RoutingReplayChoice { cli: CliId; model: string; effort: string; price?: number; costPct?: number }   // price = scarcity-weighted estimate; costPct = expected weekly-quota % of the binding pool (estimate)
export interface RoutingReplayDecision { messageId: Id; conversationId: Id; agentId?: Id; time: number; role: AgentRole; approximate: boolean; recorded: RoutingReplayChoice; baseline?: RoutingReplayChoice; alternative?: RoutingReplayChoice; changed: boolean; priceDelta?: number; costPctDelta?: number }   // approximate = the request was rebuilt from the agent record (decision recorded before 0.1.39); baseline = re-routed under the current catalog/settings, alternative = under the what-if; absent = nothing eligible
export interface RoutingReplay { generatedAt: number; assumption: string; decisions: RoutingReplayDecision[]; summary: { decisions: number; changed: number; unroutable: number; baselineMatchesRecorded: number; priceDelta: number; costPctDelta: number; moves: Array<{ from: string; to: string; count: number }> }; notes: string[] }   // assumption = the pool state both sides were judged under (recorded decisions do not store it)
export interface UsageWindow { cli: CliId; label: string; usedPct: number; resetsAt?: number; freeResetAvailable?: boolean; period?: 'session'|'weekly'; source?: 'reported'|'estimated'; model?: string; projectedPct?: number; calibrated?: boolean }   // calibrated (estimated windows): false = the budget is Harbor's fallback guess, not learned from the provider's own readings; show it as unknown/approximate
export interface Settings { routing: 'auto'|'manual'; cliOverrides: Record<CliId,{enabled:boolean}>; allowFreeReset: 'ask'|'never'; desktopNotifications?: boolean; keepRunningInBackground?: boolean; editor?: EditorId; concurrencyLimit?: number; allowedModels?: Record<CliId,string[]>; rolePreferences?: Partial<Record<Exclude<AgentRole,'main'>,RolePreference>>; effortPolicy?: EffortPolicy; lowAllowancePolicy?: LowAllowancePolicy; subscriptionReserve?: number; maxHelpersPerTurn?: number; maxPlannersPerTurn?: number; projectOverrides?: Record<Id,ProjectSettings>; cliPaths?: Record<CliId,string>; claudeOwnMcp?: boolean; spendCeilings?: SpendCeilings; secretAllowlist?: string[]; remote?: RemoteSettings; projectsDir?: string }   // projectsDir = where createProject puts new projects when no folder is given (absent = Documents\Harbor Projects; CHANGELOG 0.1.47). claudeOwnMcp: true = Claude runs also load Claude Code's own MCP servers (its user and project config, plugins, connectors), never in auto mode; absent/false = only Harbor's registry (--strict-mcp-config; CHANGELOG 0.1.36). Routing fields: absent = built-in default (CHANGELOG 0.1.12); maxHelpersPerTurn/maxPlannersPerTurn: fan-out brake per lead turn (defaults 4 and 1; CHANGELOG 0.1.23); keepRunningInBackground: absent/false = close quits; cliPaths = absolute executable path per CLI chosen in Settings, wins over HARBOR_<CLI>_PATH and PATH (merged per CLI; '' removes one; CHANGELOG 0.1.30); spendCeilings/secretAllowlist: CHANGELOG 0.1.38; remote = the local HTTP/WebSocket API (CHANGELOG 0.1.41)
export interface SpendLimit { kTokens?: number; minutes?: number }   // kTokens = billable k-tokens Harbor counted from its OWN runs (an estimate, never the provider's quota); minutes = agent-minutes (run durations summed: two helpers for 10 minutes = 20)
export interface SpendCeilings { task?: SpendLimit; day?: SpendLimit; week?: SpendLimit }   // task = one user request (concierge, lead turns, helpers it started); day/week = rolling 24 hours / 7 days. Global values count every project; a project override counts that project only (and the task value of a project override replaces the global one)
export type SpendScope = 'task'|'day'|'week';
export interface SpendStatusEntry { scope: SpendScope; projectId?: Id; limit: SpendLimit; threshold: SpendLimit; spent: { kTokens: number; minutes: number; runs: number; partial: boolean }; hit: boolean; extensions: number }   // projectId absent = counts every project; threshold = limit times (1 + extensions you allowed); partial = some runs were stopped before their final usage report (a lower bound)
export interface SpendStatus { estimate: true; entries: SpendStatusEntry[] }   // always an estimate from Harbor's own runs
export interface RemoteSettings { enabled?: boolean; host?: string; port?: number; allowFullScope?: boolean; allowPlainHttp?: boolean; tlsCertFile?: string; tlsKeyFile?: string; allowedHosts?: string[] }   // read at startup. host default 127.0.0.1; a non-loopback host needs tls* files or allowPlainHttp; allowFullScope off = full-scope tokens are refused; allowedHosts = extra Host header names accepted (tunnel names)
export type RemoteScope = 'read-only'|'answer-permissions'|'full';   // read-only = list/get methods and the event stream; answer-permissions = also answerPermission (never freeReset, never "always") and answerQuestion; full = also everything that starts, stops or changes work
export interface RemoteTokenInfo { id: Id; name: string; scope: RemoteScope; created: number; lastUsed?: number }   // the token itself is shown once by createRemoteToken and never stored in clear text
export type EffortPolicy = 'adaptive'|'conserve'|'quality';   // adaptive = by role and complexity; conserve = one effort step lower (never for retries); quality = one step higher
export type LowAllowancePolicy = 'reduceEffort'|'switch';   // absent (the default) = headroom routing: the CLI with more room in its tighter window (5h or weekly, pace-aware) takes the work once the gap is large; 'reduceEffort' = stay on the session's CLI and lower effort; 'switch' = prefer a model/CLI that is not low
export interface RolePreference { cli?: CliId; model?: string }   // a strong preference, not a hard rule: exhausted, disabled or disallowed options are still skipped
export type ProjectSettings = Pick<Settings,'concurrencyLimit'|'allowedModels'|'rolePreferences'|'effortPolicy'|'lowAllowancePolicy'|'subscriptionReserve'|'spendCeilings'|'secretAllowlist'>;   // wins over the global value per field (per CLI for allowedModels, per role for rolePreferences); spendCeilings: see SpendCeilings; secretAllowlist: added to the global list
export type HarborEvent =
 | { type:'message'; message: Message }
 | { type:'messageDelta'; messageId: Id; conversationId: Id; text: string }
 | { type:'agent'; agent: Agent }
 | { type:'conversation'; conversation: Conversation }
 | { type:'usage'; windows: UsageWindow[] }
 | { type:'cli'; cli: CliStatus }
 | { type:'permission'; requestId: Id; kind:'freeReset'|'tool'|'conflict'|'screenshot'; prompt: string; agentId?: Id; conversationId?: Id; tool?: string; alwaysAllow?: boolean; expiresAt?: number; screenshot?: ScreenshotRequestInfo }   // kind 'tool': conversationId = where the asking agent runs; tool = tool name; alwaysAllow = "always allow for this project" may be offered; expiresAt = denied automatically after this time. kind 'screenshot' (CHANGELOG 0.1.33): answer with previewScreenshot + answerScreenshot (answerPermission(id, false) also denies)
 | { type:'question'; requestId: Id; conversationId: Id; prompt: string; options?: string[]; allowText?: boolean; multiSelect?: boolean; questions?: Array<{ prompt: string; options?: string[]; allowText?: boolean; multiSelect?: boolean }>; agentId?: Id }   // an agent needs a decision (multiSelect = several options may be picked; questions = follow-up questions of the same card, answer all in one answerQuestion text); answer with answerQuestion
 | { type:'document'; projectId: Id; conversationId: Id; path: string; title?: string; agentId?: Id };   // an agent's HARBOR_OPEN_DOCUMENT passed Harbor's path checks; open it with openDocument(projectId, path, { agentId }) (CHANGELOG 0.1.34)
export type PendingPermission = Extract<HarborEvent, { type: 'permission' }>;
export interface HarborApi {
 listClis(): Promise<CliStatus[]>; refreshClis(): Promise<CliStatus[]>; openLogin(cli: CliId): Promise<void>;
 testCliPath?(cli: CliId, path: string): Promise<CliStatus>;   // runs the CLI's version and sign-in checks against this executable without saving it; rejects a path that is not an existing file (CHANGELOG 0.1.30)
 browseCliPath?(): Promise<string | null>;   // file picker for an executable; null when cancelled (CHANGELOG 0.1.30)
 listCustomClis?(): Promise<CustomCliDescriptor[]>; listCliTemplates?(): Promise<CliTemplate[]>;   // CHANGELOG 0.1.31
 dryRunCustomCli?(descriptor: CustomCliDescriptor, opts: { confirmExe: string }): Promise<CliDryRun>;   // validates, then runs version, status and one "reply OK" prompt in a temp folder; confirmExe must repeat descriptor.exe (the user's explicit OK to run that file). Saves nothing
 saveCustomCli?(descriptor: CustomCliDescriptor, opts: { confirmExe: string; replace?: boolean }): Promise<CustomCliDescriptor[]>;   // replace = update the custom CLI with the same id (otherwise a used id is refused); validates, records the executable's hash (approval), stores and re-runs discovery; also re-approves a changed file. Rejects invalid descriptors with every problem listed
 removeCustomCli?(id: CliId): Promise<CustomCliDescriptor[]>;   // returns the remaining custom CLIs
 listSkills?(projectId?: Id): Promise<Skill[]>;   // library and user-level skills; with a project also its .harbor\skills and .claude\skills. enabled is for that project (CHANGELOG 0.1.32)
 readSkill?(skillId: string, projectId?: Id): Promise<SkillDetail>;   // SKILL.md text and the file list; never runs anything
 setSkillEnabled?(skillId: string, enabled: boolean | null, projectId?: Id): Promise<Skill[]>;   // with projectId: that project's choice; without: the global default; null = back to the default
 previewSkillImport?(source: SkillImportSource, opts?: { confirmDownload?: string }): Promise<SkillImportPreview>;   // folder/zip: reads and checks, writes nothing. github: first call lists files and sizes only (network, no file content); confirmDownload = that listing's token downloads exactly those files
 importSkills?(token: string, opts?: { names?: string[] }): Promise<Skill[]>;   // copies a checked preview into the library (names = which candidates; default all usable); returns the new library skills
 removeSkill?(skillId: string): Promise<Skill[]>;   // library skills only; returns the remaining library and user-level skills
 browseSkillSource?(kind: 'folder' | 'zip'): Promise<string | null>;   // folder or .zip picker; null when cancelled
 listMcpServers?(projectId?: Id): Promise<McpServer[]>;   // Harbor's MCP registry; enabled is for that project (CHANGELOG 0.1.36)
 saveMcpServer?(server: McpServerDraft, opts?: { previousName?: string; projectId?: Id }): Promise<McpServer[]>;   // adds, or replaces previousName (a rename keeps its project choices); rejects invalid entries with every problem listed (never repeating a value)
 removeMcpServer?(name: string, opts?: { projectId?: Id }): Promise<McpServer[]>;
 setMcpServerEnabled?(name: string, enabled: boolean | null, projectId?: Id): Promise<McpServer[]>;   // with projectId: that project's choice; without: the global default; null = back to the default (off)
 testMcpServer?(server: McpServerDraft, opts?: { confirmCommand?: string }): Promise<McpTestResult>;   // stdio: starts the command (confirmCommand must repeat it) in a temp folder with the allowlisted environment plus its env, never through a shell string, stops it after initialize + tools/list or 20 s; http/sse: the same requests to the URL
 listCliMcpServers?(projectId?: Id): Promise<CliMcpServer[]>;   // servers in Claude Code's and Codex's own configuration (read-only, names and kinds only)
 listProjects(): Promise<Project[]>; addProject(path?: string): Promise<Project|null>; removeProject(id: Id): Promise<void>; setProjectImage(id: Id, image: string | null): Promise<Project>;
 listConversations(projectId: Id): Promise<Conversation[]>; newConversation(projectId: Id): Promise<Conversation>; deleteConversation(id: Id): Promise<void>;
 updateConversation(id: Id, patch: { title?: string; pinned?: boolean; archived?: boolean }): Promise<Conversation>;
 searchConversations(query: string, projectId?: Id): Promise<SearchHit[]>;
 stopConversation(id: Id): Promise<void>;
 getReview(id: Id): Promise<ReviewSnapshot>;
 openProjectFolder(id: Id): Promise<void>;
 openWorkspace?(projectId: Id, action: 'terminal' | 'editor' | 'folder', opts?: { agentId?: Id; file?: string }): Promise<void>;   // user-started: opens the project folder, or an edit helper's worktree when agentId is given, in a terminal, the chosen editor (Settings.editor, default code) or Explorer; file = path relative to that folder (editor and folder only). CHANGELOG 0.1.25
 getGitOverview(projectId: Id): Promise<GitOverview>;
 getGitLog(projectId: Id, opts?: { branch?: string; limit?: number; skip?: number }): Promise<GitCommit[]>;   // no branch = all local branches, newest first, topological; skip = commits to skip (paging)
 getGitLogPage?(projectId: Id, opts?: { branch?: string; limit?: number; skip?: number }): Promise<{ commits: GitCommit[]; hasMore: boolean; note?: string }>;   // same as getGitLog plus hasMore, and a note when git timed out instead of an empty list that looks like no commits
 getGitChanges(projectId: Id, target?: GitTarget): Promise<GitFileChange[]>;   // branch = since its merge-base with base, plus its worktree's uncommitted work
 getGitDiff(projectId: Id, path: string, target?: GitTarget): Promise<string>;
 listMessages(conversationId: Id, opts?: { before?: Id | number; limit?: number }): Promise<Message[]>;   // no opts = the whole conversation; limit = only the newest N (ascending); before = a message id or epoch ms, page backwards from there
 send(conversationId: Id, text: string, attachments?: { name: string; mime: string; dataBase64: string }[], opts?: { steer?: boolean }): Promise<void>;   // images only: png/jpeg/gif/webp, max 10 MB each, max 6. opts.steer: when the lead is mid-turn, cut that turn short and act on this message now instead of after it. CHANGELOG 0.1.26
 setConversationMode(conversationId: Id, mode: ConversationMode, goal?: string): Promise<Conversation>;   // goal mode requires a goal
 setConversationDeadline?(conversationId: Id, deadline: number | null): Promise<Conversation>;   // epoch ms the owner needs the work by; null clears it. Routing turns it into urgency (CHANGELOG 0.1.27)
 listAgents(projectId: Id): Promise<Agent[]>; openAgentConversation(agentId: Id): Promise<Conversation>; stopAgent(agentId: Id, conversationId?: Id): Promise<void>;   // also cancels a queued assignment; conversationId (the lead only) = the open conversation: only its turn and helpers stop (CHANGELOG 0.1.45)
 setAgentPriority(agentId: Id, priority: number): Promise<void>; pauseAgent(agentId: Id): Promise<void>; resumeAgent(agentId: Id): Promise<void>;   // pause only holds queued work back; a running agent keeps running
 resumeAgentSession(agentId: Id): Promise<void>;   // continue a stopped helper in its saved CLI session (rejects when it is not stopped or has no session)
 integrateBranches(projectId: Id, agentIds: Id[], target?: string): Promise<Agent>;   // queue an integrator that merges these helpers' approved harbor/* branches into a new harbor/integrate-* branch; target = branch to apply to later (default: the project's checked-out branch)
 applyIntegration(agentId: Id): Promise<Agent>;   // fast-forward the integration's (or rollback's) target to its head; rejects unless done, the project folder is clean and the target is still at base. Never pushes or forces
 getChanges(agentId: Id): Promise<GitFileChange[]>;   // committed files changed on a helper's branch (since its base) or an integration (base..head); [] when the agent has no branch
 previewRollback(agentId: Id, target?: string): Promise<RollbackPreview>;   // what undoing this task's merges on target (default: the checked-out branch) would revert, conflict with and affect. Read-only: changes no ref, index or file
 rollbackTask(agentId: Id, target?: string): Promise<Agent>;   // queue a rollback agent that reverts the task's merges on a new harbor/rollback-* branch and runs the checks; apply it with applyIntegration. Never touches target itself
 getUsage(): Promise<UsageWindow[]>;
 getSettings(): Promise<Settings>; setSettings(s: Partial<Settings>): Promise<Settings>;
 answerPermission(requestId: Id, allow: boolean, opts?: { always?: boolean }): Promise<void>;   // always = (tool requests with alwaysAllow) also store a project rule; ignored elsewhere
 previewScreenshot?(requestId: Id, opts?: { sourceId?: string }): Promise<ScreenshotSource[]>;   // live preview for a pending screenshot request: every window and screen with a small thumbnail taken now; sourceId = only that one, larger. Call again to refresh. Nothing is stored or sent (CHANGELOG 0.1.33)
 answerScreenshot?(requestId: Id, answer: { allow: boolean; sourceId?: string; forConversation?: boolean }): Promise<void>;   // allow needs a sourceId this request's preview returned (the user's choice, never the agent's); forConversation = later window requests in this conversation capture that same window without asking (windows only, never screens)
 openDocument?(projectId: Id, path: string, opts?: { agentId?: Id; since?: number }): Promise<DocumentResult>;   // read-only view of a file inside the project, an agent's worktree, the project's conversation attachments, Harbor's skills library, or a file the user picked with pickDocument; relative paths resolve against agentId's worktree (else the project). since = the `modified` already shown: an unchanged file comes back with unchanged and no content (CHANGELOG 0.1.34)
 pickDocument?(projectId: Id): Promise<DocumentResult | null>;   // native file dialog; the chosen file may then be opened, refreshed and acted on for the rest of the session. null when cancelled
 documentAction?(projectId: Id, path: string, action: 'openExternal' | 'reveal', opts?: { agentId?: Id }): Promise<void>;   // user-started; same path checks as openDocument. openExternal only for documents and images (canOpenExternally); reveal selects the file in Explorer
 pathForFile?(file: File): string;   // preload only, not an IPC method: the local path of a file dropped on the window ('' when it has none)
 listToolRules(projectId: Id): Promise<ToolRule[]>; removeToolRule(projectId: Id, ruleId: Id): Promise<ToolRule[]>;   // "always allow for this project" rules; remove returns the remaining rules
 listPendingPermissions(): Promise<PendingPermission[]>;   // permission requests still waiting for an answer (a reloaded renderer misses the events); same fields as the `permission` event
 answerQuestion(requestId: Id, answer: string): Promise<void>;   // delivered into the asking agent's conversation as the user's message
 renameProject?(id: Id, name: string): Promise<Project>;   // trims; 1-120 characters; the folder on disk is untouched. CHANGELOG 0.1.44
 createProject?(draft: NewProjectDraft): Promise<CreateProjectResult>;   // folder, template files, git init + first commit, optional private GitHub repo (via gh), registration. Desktop only. CHANGELOG 0.1.47
 previewDeleteProject?(id: Id): Promise<DeletePreview>;   // read-only
 deleteProject?(id: Id, scope: DeleteScope, confirmName?: string): Promise<DeleteResult>;   // 'forget' is removeProject; the other scopes need confirmName = the project name when the preview says so (always for 'folder'). Never touches the GitHub remote
 previewPush?(projectId: Id, branch: string): Promise<PushPreview>;
 pushBranch?(projectId: Id, branch: string, opts?: { setUpstream?: boolean; allowDefaultBranch?: boolean; secretOverride?: string }): Promise<PushResult>;   // plain push, never forced; the default branch needs allowDefaultBranch; blocked by unallowlisted secret findings
 createPullRequest?(projectId: Id, draft: PullRequestDraft): Promise<{ url: string }>;   // pushes the branch if needed, then gh pr create
 setRemote?(projectId: Id, url: string, opts?: { replace?: boolean }): Promise<void>;   // adds origin (https or ssh URL only); changing an existing origin needs replace
 cloneProject?(draft: CloneProjectDraft): Promise<CreateProjectResult>;   // git clone into the projects folder (a non-empty target is refused; a failed clone removes only the folder this call made), registers the project, origin = the URL. Desktop only. CHANGELOG 0.1.48
 listGithubRepos?(opts?: GithubRepoListOptions): Promise<GithubRepo[]>;   // the signed-in account's (or one owner's) repositories through gh, cached for 5 minutes; rejects with the fix when gh is missing or signed out
 listWorktrees?(): Promise<WorktreeInfo[]>;   // every worktree folder under Harbor's own folder, across projects (Settings > Storage). Read-only
 cleanupWorktrees?(paths?: string[]): Promise<{ removed: number; branchesDeleted: number; warnings: string[] }>;   // removes the removable ones (only the given paths when passed); a harbor/* branch is deleted only when merged
 browseFolder?(): Promise<string | null>;   // folder picker (Settings > Projects folder); null when cancelled. Desktop only
 getGithubStatus?(): Promise<GithubStatus>;   // is gh installed and signed in (no token is read)
 listProjectNotes?(projectId: Id): Promise<ProjectNote[]>; removeProjectNote?(projectId: Id, noteId: Id): Promise<ProjectNote[]>;   // project knowledge notes, oldest first; remove returns the remaining notes (unknown note id = no-op; both reject an unknown project). CHANGELOG 0.1.40
 exportDiagnostics?(): Promise<string>;   // redacted plain-text support bundle (versions, CLI states, counts, journal and log tails); contains no message text, prompts or credentials
 previewBundleExport?(projectId: Id, selection: BundleSelection): Promise<BundleExportPreview>;   // builds the bundle in memory (paths rewritten, secret scan run) and lists exactly what goes in; writes nothing (CHANGELOG 0.1.35)
 exportBundle?(token: string, opts?: { keepSecrets?: boolean; redactSecrets?: boolean }): Promise<BundleExportResult | null>;   // save dialog, then writes that preview's .harbor.zip; with secret findings one of keepSecrets/redactSecrets is required. null when cancelled
 browseImportFile?(kind: 'bundle' | 'chatExport'): Promise<string | null>;   // file picker for a .harbor.zip, or an account export (conversations.json or its .zip); null when cancelled
 previewBundle?(path: string): Promise<BundlePreview>;   // reads and checks a bundle (archive safeguards as for skills; a newer bundle version is refused); writes nothing
 importBundle?(token: string, opts: BundleImportOptions): Promise<BundleImportResult>;   // brings the chosen parts into an existing project: new ids, conversations as read-only imported history, skills into the library (name collisions keep both), never overwrites without replaceSettings
 listImportSources?(): Promise<ChatImportSourceInfo[]>;   // the chat importers and whether their folder exists; reads no transcript
 previewImport?(source: ChatImportSourceId, opts?: { path?: string }): Promise<ChatImportPreview>;   // folder sources: lists the chat files (names, dates, sizes) without reading them; file sources: reads the picked export (path) and lists its chats
 importConversation?(projectId: Id, token: string, entryIds: string[]): Promise<ChatImportResult>;   // reads only the chosen entries and adds them to the project as read-only conversations tagged imported
 continueImported?(conversationId: Id, opts: { cli: CliId }): Promise<Conversation>;   // a new conversation whose lead gets Harbor's handoff of the imported chat (a summary framed as quoted history, never a replay or a native resume) and prefers that CLI
 getSpendStatus?(projectId?: Id, conversationId?: Id): Promise<SpendStatus>;   // spend against the configured ceilings (estimate from Harbor's own runs). No projectId = global ceilings only; conversationId adds that conversation's current task. CHANGELOG 0.1.38
 getTaskReport?(conversationId: Id): Promise<TaskReport>;   // tokens, estimated quota, minutes and which CLI/model did what for one conversation (lead + its helpers), from Harbor's own usage records (kept 8 days). CHANGELOG 0.1.39
 rateResult?(targetId: Id, rating: ResultRatingValue, note?: string): Promise<ResultRating>;   // targetId = an agent id or a routed message id; rating the same target again replaces the earlier rating. CHANGELOG 0.1.39
 listRatings?(opts?: { projectId?: Id }): Promise<ResultRating[]>;   // newest first
 getRatingSummary?(opts?: { projectId?: Id; by?: 'cli'|'model'|'need' }): Promise<RatingSummaryRow[]>;   // by: default 'model' (cli + model); 'need' counts a rating once per need of the rated work
 replayRouting?(opts?: RoutingReplayOptions): Promise<RoutingReplay>;   // what-if: re-routes recorded decisions under another catalog/settings; read-only. CHANGELOG 0.1.39
 createRemoteToken?(name: string, scope: RemoteScope): Promise<{ token: string; info: RemoteTokenInfo }>;   // a per-device bearer token for the remote API; the token is returned only here. Full scope needs Settings.remote.allowFullScope. Desktop only: never callable remotely (CHANGELOG 0.1.41)
 listRemoteTokens?(): Promise<RemoteTokenInfo[]>;   // without the tokens themselves
 revokeRemoteToken?(id: Id): Promise<void>;   // unknown id = no-op; open remote connections using it are closed
 onEvent(cb: (e: HarborEvent) => void): () => void;   // returns unsubscribe
}
declare global { interface Window { harbor: HarborApi } }
